begin;
select no_plan();
select has_table('app'::name,'catalog_draft_heads'::name);
select ok(not has_function_privilege('anon','api_v1.get_catalog_workspace_v1(uuid)','execute'),'anonymous cannot read drafts');
select ok(not has_table_privilege('authenticated','app.catalog_draft_heads','update'),'there is no raw draft write grant');
select set_config('test.booking_snapshots',(select md5(coalesce(jsonb_agg(to_jsonb(b) order by b.id)::text,'')) from app.bookings b),true);
select set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1"}',true);
set local role authenticated;
select throws_like($$select api_v1.get_catalog_workspace_v1('a0000000-0000-0000-0000-000000000001')$$,'%not_authorized%','staff cannot author catalog');
reset role;
select set_config('request.jwt.claims','{"sub":"a1000000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select is((api_v1.get_catalog_workspace_v1('a0000000-0000-0000-0000-000000000001')->>'can_publish')::boolean,true,'administrator may publish');
select throws_like($$select api_v1.get_catalog_workspace_v1('b0000000-0000-0000-0000-000000000001')$$,'%not_authorized%','catalog read is tenant-scoped');
select set_config('test.catalog_base',(select e::text from jsonb_array_elements(api_v1.get_catalog_workspace_v1('a0000000-0000-0000-0000-000000000001')->'entities') e where e->>'id'='a7200000-0000-0000-0000-000000000001'),true);
select set_config('test.catalog_document',((current_setting('test.catalog_base')::jsonb-array['id','kind','revision','state'])||jsonb_build_object('currency','USD','price_minor',4200,'policy',jsonb_build_object('consent_text','I agree to the booking terms.','consent_version','2'),'policy_ar',jsonb_build_object('consent_text','أوافق على شروط الحجز.','consent_version','2')))::text,true);
select is((api_v1.save_catalog_entity_v1('a0000000-0000-0000-0000-000000000001','a9e00000-0000-4000-8000-000000000001','service','a7200000-0000-0000-0000-000000000001',1,current_setting('test.catalog_document')::jsonb)->>'state'),'draft','service edit saves a draft');
select is((api_v1.save_catalog_entity_v1('a0000000-0000-0000-0000-000000000001','a9e00000-0000-4000-8000-000000000001','service','a7200000-0000-0000-0000-000000000001',1,current_setting('test.catalog_document')::jsonb)->>'replayed')::boolean,true,'draft retry returns its first result');
select throws_like($$select api_v1.save_catalog_entity_v1('a0000000-0000-0000-0000-000000000001','a9e00000-0000-4000-8000-000000000002','service','a7200000-0000-0000-0000-000000000001',1,current_setting('test.catalog_document')::jsonb)$$,'%revision_conflict%','stale draft cannot overwrite another save');
select throws_like($$select api_v1.save_catalog_entity_v1('a0000000-0000-0000-0000-000000000001','a9e00000-0000-4000-8000-000000000001','service','a7200000-0000-0000-0000-000000000001',1,jsonb_set(current_setting('test.catalog_document')::jsonb,'{price_minor}','4300'))$$,'%idempotency_conflict%','changed price cannot reuse a draft attempt');
select is((select price_minor from api_v1.get_public_catalog_v1('client.tenant-a.example.invalid','en') limit 1),18000::bigint,'public catalog still has the original published price');
select set_config('test.catalog_revisions',(select jsonb_object_agg(e->>'id',e->'revision')::text from jsonb_array_elements(api_v1.get_catalog_workspace_v1('a0000000-0000-0000-0000-000000000001')->'entities') e where e->>'state'='draft'),true);
select throws_like($$select api_v1.publish_catalog_workspace_v1('a0000000-0000-0000-0000-000000000001','a9e00000-0000-4000-8000-000000000003','{}')$$,'%revision_conflict%','publication must review all draft revisions');
select is((api_v1.publish_catalog_workspace_v1('a0000000-0000-0000-0000-000000000001','a9e00000-0000-4000-8000-000000000004',current_setting('test.catalog_revisions')::jsonb)->>'revision')::integer,2,'publication produces a new complete aggregate');
select is((select price_minor from api_v1.get_public_catalog_v1('client.tenant-a.example.invalid','en') limit 1),4200::bigint,'published English price reflects the draft');
select is((select price_minor from api_v1.get_public_catalog_v1('client.tenant-a.example.invalid','ar') limit 1),4200::bigint,'published Arabic price agrees');
select is((select location_name from api_v1.get_public_catalog_v1('client.tenant-a.example.invalid','en') limit 1),'Downtown','unchanged location remains in the aggregate');
select is((api_v1.publish_catalog_workspace_v1('a0000000-0000-0000-0000-000000000001','a9e00000-0000-4000-8000-000000000004',current_setting('test.catalog_revisions')::jsonb)->>'replayed')::boolean,true,'publication retry does not create another aggregate');
reset role;
select is((select md5(coalesce(jsonb_agg(to_jsonb(b) order by b.id)::text,'')) from app.bookings b),current_setting('test.booking_snapshots'),'publication never changes historical booking snapshots');
select ok(not exists(select 1 from app.catalog_authoring_events where result::text like '%consent_text%' or result::text like '%policy%'),'audit excludes policy text and draft values');
select * from finish();
rollback;
